package com.bankpli.javabank.config;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin")public class AdminController{private final ConfigService config;private final KycService kyc;public AdminController(ConfigService c,KycService k){config=c;kyc=k;}@GetMapping("/config")public Map<String,String>config(){return config.all();}@PutMapping("/config/{key}")public Map<String,String>put(@PathVariable String key,@RequestBody Map<String,String>b){return Map.of(key,config.put(key,b.get("value")));}public record KycRequest(String legalName,String documentId,String password){}@PostMapping("/kyc")public KycService.Result kyc(@RequestBody KycRequest r){return kyc.validate(r.legalName(),r.documentId(),r.password());}}
